# AfraKala PROD-DISCOVERY embedded runner (ASCII + UTF8 BOM). No GitHub .ps1 download.
# Read-only. Paste/run this whole file on production PowerShell 5.1.
$ErrorActionPreference = 'Stop'
$dir = Join-Path $env:TEMP 'afrakala-cutover'
New-Item -ItemType Directory -Force -Path $dir | Out-Null
$script = Join-Path $dir 'PROD-DISCOVERY.ps1'
$outFile = Join-Path $dir 'PROD-DISCOVERY.out.txt'
$b64 = @'

'@
$bytes = [Convert]::FromBase64String(($b64 -replace '\s',''))
[System.IO.File]::WriteAllBytes($script, $bytes)
Write-Host ('Wrote ' + $script + ' bytes=' + $bytes.Length)
Write-Host ('SHA256=' + (Get-FileHash $script -Algorithm SHA256).Hash)
powershell -NoProfile -ExecutionPolicy Bypass -File $script | Tee-Object -FilePath $outFile
Write-Host ''
Write-Host ('Saved: ' + $outFile)
try { notepad $outFile } catch {}